<script setup lang="ts">import {reactive,watch} from 'vue'; const props=defineProps<{modelValue?:Record<string,unknown>|null}>(); const emit=defineEmits<{save:[value:Record<string,unknown>];cancel:[]}>(); const form=reactive({status:'',result:''}); watch(()=>props.modelValue,v=>Object.assign(form,{status:'',result:'',...(v||{})}),{immediate:true});</script>
<template><form class="work-item-form" @submit.prevent="emit('save',{...form})"><label>招投标状态<select v-model="form.status"><option value="" disabled>请选择状态</option><option>进行中</option><option>已结束</option></select></label><label>结果<select v-model="form.result"><option value="">请选择结果</option><option>中标</option><option>未中标</option></select></label><div class="form-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button class="primary">保存</button></div></form></template>
